      "kind": "definition",
      "type": "(R : Type u_1) → {A : Type u_3} → [inst : CommRing R] → [inst_1 : Ring A] → [Algebra R A] → A → Prop"
    },
    {
      "name": "minpoly.IsIntegrallyClosed.degree_le_of_ne_zero",
      "module_name": "Mathlib.FieldTheory.Minpoly.IsIntegrallyClosed",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [inst_1 : CommRing S] [IsDomain R] [inst_3 : Algebra R S]\n  [IsIntegrallyClosed R] [IsDomain S] [Module.IsTorsionFree R S] {s : S} {p : Polynomial R},\n  p ≠ 0 → (Polynomial.aeval s) p = 0 → (minpoly R s).degree ≤ p.degree"
    },
    {
      "name": "RingHom.IsIntegralElem",
      "module_name": "Mathlib.RingTheory.IntegralClosure.IsIntegral.Defs",
      "kind": "definition",
      "type": "{R : Type u_1} → {A : Type u_3} → [inst : CommRing R] → [inst_1 : Ring A] → (R →+* A) → A → Prop"
    },
    {
      "name": "minpoly.monic",
      "module_name": "Mathlib.FieldTheory.Minpoly.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} {B : Type u_2} [inst : CommRing A] [inst_1 : Ring B] [inst_2 : Algebra A B] {x : B},\n  IsIntegral A x → (minpoly A x).Monic"
    },
    {
      "name": "Polynomial.exists_monic_aeval_eq_zero_forall_mem_pow_of_isIntegral",
      "module_name": "Mathlib.RingTheory.IntegralClosure.Algebra.Ideal",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S] {I : Ideal R} {x : S},\n  IsIntegral (↥(Algebra.adjoin R {x | ∃ r ∈ I, Polynomial.C r * Polynomial.X = x})) (Polynomial.C x * Polynomial.X) →\n    ∃ p, p.Monic ∧ (Polynomial.aeval x) p = 0 ∧ ∀ (i : ℕ), p.coeff i ∈ I ^ (p.natDegree - i)"
    },
    {
      "name": "IsIntegral.of_aeval_monic",
      "module_name": "Mathlib.RingTheory.IntegralClosure.IsIntegral.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_2} [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : Algebra R A] {x : A}\n  {p : Polynomial R}, p.Monic → p.natDegree ≠ 0 → IsIntegral R ((Polynomial.aeval x) p) → IsIntegral R x"
    },
    {
      "name": "integralClosure.isIntegral",
      "module_name": "Mathlib.RingTheory.IntegralClosure.IsIntegralClosure.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_2} [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : Algebra R A]\n  (x : ↥(integralClosure R A)), IsIntegral R x"
    }
  ]
}
